import { BasketPage } from '../pages/basket-page';
import {
  AddressSelectPage,
  DeliveryMethodPage,
  OrderCompletionPage,
  OrderHistoryPage,
  OrderSummaryPage,
  PaymentPage,
  WalletPage,
} from '../pages/checkout-pages';
import { LoginPage } from '../pages/login-page';
import { NavBar } from '../pages/nav-bar';
import { ProductListPage } from '../pages/product-list-page';
import { Customer, ShopApi } from './shop-api';

export interface ShopPages {
  navBar: NavBar;
  loginPage: LoginPage;
  productList: ProductListPage;
  basket: BasketPage;
  addressSelect: AddressSelectPage;
  deliveryMethod: DeliveryMethodPage;
  payment: PaymentPage;
  orderSummary: OrderSummaryPage;
  orderCompletion: OrderCompletionPage;
  orderHistory: OrderHistoryPage;
  wallet: WalletPage;
}

interface ShopFixtures {
  api: ShopApi;
  shop: ShopPages;
}

export const test = base.extend<ShopFixtures>({
  page: async ({ page, context, baseURL }, use) => {
    // Hide the cookie banner (see test-cases/README.md).
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL! }]);
    await use(page);
  },

  api: async ({ request }, use) => {
    await use(new ShopApi(request));
  },

  shop: async ({ page }, use) => {
    await use({
      navBar: new NavBar(page),
      loginPage: new LoginPage(page),
      productList: new ProductListPage(page),
      basket: new BasketPage(page),
      addressSelect: new AddressSelectPage(page),
      deliveryMethod: new DeliveryMethodPage(page),
      payment: new PaymentPage(page),
      orderSummary: new OrderSummaryPage(page),
      orderCompletion: new OrderCompletionPage(page),
      orderHistory: new OrderHistoryPage(page),
      wallet: new WalletPage(page),
    });
  },
});

export { expect } from '@playwright/test';

/** Logs the customer in the browser with the session of the API login, as the login form does. */
export async function loginInBrowser(page: Page, customer: Customer, baseURL: string): Promise<void> {
  await page.context().addCookies([{ name: 'token', value: customer.token, url: baseURL }]);
  await page.addInitScript(({ token, basketId }) => {
    window.localStorage.setItem('token', token);
    window.sessionStorage.setItem('bid', String(basketId));
  }, { token: customer.token, basketId: customer.basketId });
}
"}
